import Foundation

/// Adobe Core14 Helvetica AFM metrics (advance widths and pair kerning, WinAnsi range)
/// as used by react-pdf/pdfkit for its standard fonts. Generated by
/// `scripts/gen-helvetica-metrics.cjs` into `Resources/helvetica-metrics.json`.
struct HelveticaMetrics: Sendable {
    struct Font: Sendable {
        /// Unicode scalar → advance (1/1000 em).
        var widths: [UInt32: Double]
        /// (left, right) scalars → kerning adjustment (1/1000 em).
        var kerning: [UInt64: Double]

        func width(_ scalar: Unicode.Scalar) -> Double? {
            widths[scalar.value]
        }

        func kern(_ left: Unicode.Scalar, _ right: Unicode.Scalar) -> Double {
            kerning[UInt64(left.value) << 32 | UInt64(right.value)] ?? 0
        }
    }

    var fonts: [String: Font]

    static let shared: HelveticaMetrics? = {
        guard let url = Bundle.module.url(forResource: "helvetica-metrics", withExtension: "json"),
              let data = try? Data(contentsOf: url),
              let raw = try? JSONDecoder().decode(Raw.self, from: data) else { return nil }
        var fonts: [String: Font] = [:]
        for (name, font) in raw.fonts {
            var widths: [UInt32: Double] = [:]
            for (key, width) in font.widths { if let scalar = UInt32(key) { widths[scalar] = width } }
            var kerning: [UInt64: Double] = [:]
            for (key, value) in font.kerning {
                let parts = key.split(separator: ",").compactMap { UInt64($0) }
                if parts.count == 2 { kerning[parts[0] << 32 | parts[1]] = value }
            }
            fonts[name] = Font(widths: widths, kerning: kerning)
        }
        return HelveticaMetrics(fonts: fonts)
    }()

    private struct Raw: Decodable {
        struct RawFont: Decodable {
            var widths: [String: Double]
            var kerning: [String: Double]
        }
        var fonts: [String: RawFont]
    }
}
